<script lang="ts">let {route}:{route:[number,number][]}=$props();let lats=$derived(route.map(p=>p[0])),lons=$derived(route.map(p=>p[1])),lat=$derived(lats.reduce((a,b)=>a+b,0)/Math.max(lats.length,1)),minx=$derived(Math.min(...lons)*Math.cos(lat*Math.PI/180)),maxx=$derived(Math.max(...lons)*Math.cos(lat*Math.PI/180)),miny=$derived(Math.min(...lats)),maxy=$derived(Math.max(...lats)),scale=$derived(Math.min(310/(maxx-minx||1),128/(maxy-miny||1))),width=$derived((maxx-minx)*scale),height=$derived((maxy-miny)*scale),points=$derived(route.map(([a,b])=>[179-width/2+(b*Math.cos(lat*Math.PI/180)-minx)*scale,88+height/2-(a-miny)*scale])),path=$derived(points.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`).join(' '));</script><svg class="map" viewBox="0 0 358 176" role="img" aria-label="Workout route">{#if route.length>1}<defs><linearGradient id="route-gradient"><stop stop-color="#FFB547"/><stop offset=".5" stop-color="#FF8A3D"/><stop offset="1" stop-color="#FF6B6B"/></linearGradient></defs><path d={path} stroke="#FF8A3D" stroke-opacity=".14" stroke-width="13" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d={path} stroke="url(#route-gradient)" stroke-width="4.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/><circle cx={points[0][0]} cy={points[0][1]} r="7" fill="#3DDC97" stroke="#0E1424" stroke-width="3"/>{:else}<text x="179" y="91" fill="#69728A" text-anchor="middle">No route recorded</text>{/if}</svg><style>.map{width:100%;display:block;background:#0E1424;border-radius:16px}</style>